do $vera_lz$
declare
 d bytea:=decode('','base64');
 o bytea:=''::bytea;
 p integer:=0;
 t integer;
 n integer;
 z integer;
 k integer;
 s text;
begin
 while p<octet_length(d) loop
  t:=get_byte(d,p);p:=p+1;
  if t<128 then
   o:=o||substring(d from p+1 for t);p:=p+t;
  else
   n:=t-125;z:=get_byte(d,p)*256+get_byte(d,p+1);p:=p+2;
   for k in 1..n loop o:=o||substring(o from octet_length(o)-z+1 for 1);end loop;
  end if;
 end loop;
 foreach s in array string_to_array(convert_from(o,'UTF8'),chr(30)) loop execute s;end loop;
end;
$vera_lz$;
